extern int printf(const char*,...);extern int fflush(void*);typedef unsigned long long U;
int n,r,m,E[56],V[56][8],deg[8],sums[8],weights[56],es[56];long tested,ones,tries;U rng=138;
U randx(){rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;return rng;}
int good(){for(int j=0;j<m;j++){int v=sums[V[es[j]][0]],same=1;for(int k=1;k<r;k++)if(sums[V[es[j]][k]]!=v){same=0;break;}if(same)return 0;}return 1;}
int rec(int j){if(j==m)return good();for(int w=1;w<=3;w++){for(int k=0;k<r;k++)sums[V[es[j]][k]]+=w;if(rec(j+1))return 1;for(int k=0;k<r;k++)sums[V[es[j]][k]]-=w;}return 0;}
int main(){for(n=3;n<=6;n++)for(r=3;r<=n;r++){int ne=0;tested=ones=tries=0;for(int mask=0;mask<(1<<n);mask++)if(__builtin_popcount(mask)==r){E[ne]=mask;int k=0;for(int v=0;v<n;v++)if(mask>>v&1)V[ne][k++]=v;ne++;}if(ne>20)continue;for(U mask=0;mask<(1ULL<<ne);mask++){m=0;for(int v=0;v<n;v++)deg[v]=0;for(int i=0;i<ne;i++)if(mask>>i&1){es[m++]=i;for(int k=0;k<r;k++)deg[V[i][k]]++;}int isolated=0;for(int j=0;j<m;j++){int all=1;for(int k=0;k<r;k++)if(deg[V[es[j]][k]]!=1)all=0;if(all)isolated=1;}if(isolated)continue;tested++;for(int v=0;v<n;v++)sums[v]=deg[v];if(good()){ones++;continue;}int ok=0;for(int t=0;t<100&&!ok;t++){for(int v=0;v<n;v++)sums[v]=0;for(int j=0;j<m;j++){int w=1+randx()%3;for(int k=0;k<r;k++)sums[V[es[j]][k]]+=w;}ok=good();}if(!ok){tries++;for(int v=0;v<n;v++)sums[v]=0;if(!rec(0)){printf("FAIL n=%d r=%d mask=%llu\n",n,r,mask);return 0;}}}printf("n=%d r=%d all=%llu eligible=%ld ones=%ld exact_fallback=%ld NO_COUNTEREXAMPLE\n",n,r,1ULL<<ne,tested,ones,tries);fflush(0);}}
